import { describe, expect, it } from "vitest";
import { csvMeta } from "../csv";

describe("csvMeta", () => {
	it("writes plain lines as they are", () => {
		expect(csvMeta(["Generated by Retrospend", "Project: Trip", ""])).toBe(
			"Generated by Retrospend\nProject: Trip\n\n",
		);
	});

	it("keeps a name with a line break inside one quoted cell", () => {
		const out = csvMeta(['Project: Trip\n=HYPERLINK("http://x")', "Total: 1"]);
		expect(out).toBe('"Project: Trip\n=HYPERLINK(""http://x"")"\nTotal: 1\n');
	});

	it("quotes a name with a comma and neutralizes a leading formula character", () => {
		expect(csvMeta(["Project: A, B"])).toBe('"Project: A, B"\n');
		expect(csvMeta(["=1+1"])).toBe("'=1+1\n");
	});
});
